"""Executed only in the existing offline fixture harness before migration021."""
migration=(root/'supabase/migrations/202610150021_retire_womans_meeting.sql').read_text()
rpc('task_app_setup',"'bootstrap',null",owner)
category=sql(f"select id from public.categories where owner_id='{owner}'and name='Woman''s Meeting';")
other_category=sql(f"select id from public.categories where owner_id='{owner}'and name='Sunday Service';")
pure=sql(f"insert into public.task_series(owner_id,assigned_to_member_id)values('{owner}','{ownmember}')returning id;")
mixed=sql(f"insert into public.task_series(owner_id,assigned_to_member_id)values('{owner}','{ownmember}')returning id;")
sql("update public.task_fine_configuration set enabled_at=now()-interval '1 day';")
def task(name,cat,series,deleted=False):
 ordinal=sql(f"select coalesce(max(occurrence_number),-1)+1 from public.tasks where series_id='{series}';")
 return sql(f"insert into public.tasks(owner_id,title,notes,status,priority,category_id,weekdays,series_id,occurrence_number,assigned_to_member_id,due_date,due_time,deleted_at)values('{owner}','{name}','Preserve unrelated data','active','medium','{cat}','{{}}','{series}',{ordinal},'{ownmember}',(now()at time zone 'Asia/Kolkata')::date+8,'23:50',{'now()' if deleted else 'null'})returning id;")
first=task('Retire active occurrence',category,pure)
second=task('Retire Bin occurrence',category,mixed,True)
retained=task('Retained Sunday occurrence',other_category,mixed)
# Queue one removed occurrence and one different meeting with a removed source.
for source,series,cat in [(first,pure,category),(second,mixed,other_category)]:
 sql(f"insert into public.task_repeat_pending(id,owner_id,source_task_id,series_id,occurrence_number,due_date,payload)select gen_random_uuid(),'{owner}','{source}','{series}',2,(now()at time zone 'Asia/Kolkata')::date+15,to_jsonb(t)||jsonb_build_object('category_id','{cat}')from public.tasks t where t.id='{source}';")
absence_id=sql(f"insert into public.account_member_absences(owner_id,member_id,category_id,created_at,expires_at)values('{owner}','{mm}','{category}',now()-interval '1 day',now()+interval '1 day')returning id;")
sql(f"insert into public.task_coverage_claims(task_id,absence_id,owner_id,original_member_id,taken_by_member_id)values('{first}','{absence_id}','{owner}','{mm}','{ownmember}');")
# Established yearly credits survive permanent task deletion by existing policy.
sql(f"insert into public.member_task_completions(owner_id,task_id,member_id,completed_at,completion_year)values('{owner}','{first}','{ownmember}',now(),2026);insert into public.member_completion_totals(owner_id,member_id,completion_year,completed_count)values('{owner}','{ownmember}',2026,1);")
sql(f"insert into public.task_fines(owner_id,task_id,title,category_name,member_id,member_name,cutoff_at)values('{owner}','{retained}','Retained issued fine','Sunday Service','{ownmember}','Existing Owner Name',now());")
other_task=sql(f"select to_jsonb(t)from public.tasks t where id='{retained}';")
pending=sql(f"select payload from public.task_repeat_pending where source_task_id='{second}';")
grants=sql("select jsonb_object_agg(proname,coalesce(proacl::text,''))from pg_proc where pronamespace='public'::regnamespace and proname in('task_app_setup','task_app_mark_absent','task_app_history_expires','task_app_fine_cutoff');")
accounts=sql('select count(*)from auth.users;')
# A claim on another category must never silently lose its provenance.
sql(f"insert into public.task_coverage_claims(task_id,absence_id,owner_id,original_member_id,taken_by_member_id)values('{retained}','{absence_id}','{owner}','{mm}','{ownmember}');")
sql(migration,fail='Cross-category claims require separate preservation review')
check('cross-category claim refusal rolls back all retirement work',sql(f"select count(*)from public.tasks where id in('{first}','{second}');")=='2')
sql(f"delete from public.task_coverage_claims where task_id='{retained}';")
sql(f"insert into public.task_fines(owner_id,task_id,title,category_name,member_id,member_name,cutoff_at)values('{owner}','{first}','Needs separate review','Woman''s Meeting','{ownmember}','Existing Owner Name',now());")
sql(migration,fail='Issued fine records require separate review')
check('issued retired fine refusal rolls back all retirement work',sql(f"select count(*)from public.categories where id='{category}';")=='1')
sql(f"delete from public.task_fines where task_id='{first}';")
sql(migration)
check('active and Bin retired tasks physically removed',sql(f"select count(*)from public.tasks where id in('{first}','{second}');")=='0')
check('retired category and absence removed',sql(f"select count(*)from public.categories where id='{category}';")=='0'and sql(f"select count(*)from public.account_member_absences where id='{absence_id}';")=='0')
check('retired queue removed and no retired fine issued',sql(f"select count(*)from public.task_repeat_pending where series_id='{pure}';")=='0'and sql("select count(*)from public.task_fines where category_name='Woman''s Meeting';")=='0')
check('pure retired series removed but mixed series retained',sql(f"select count(*)from public.task_series where id='{pure}';")=='0'and sql(f"select count(*)from public.task_series where id='{mixed}';")=='1')
check('other meeting task unchanged exactly',sql(f"select to_jsonb(t)from public.tasks t where id='{retained}';")==other_task)
check('other meeting future payload retained and safely detached',sql(f"select payload from public.task_repeat_pending where series_id='{mixed}';")==pending and sql(f"select source_task_id is null from public.task_repeat_pending where series_id='{mixed}';")=='t')
check('issued other fine and activation preserved',sql(f"select count(*)from public.task_fines where task_id='{retained}';")=='1'and sql('select enabled_at is not null from public.task_fine_configuration;')=='t')
check('annual total and credited occurrence preserved',sql(f"select completed_count from public.member_completion_totals where owner_id='{owner}'and member_id='{ownmember}'and completion_year=2026;")=='1'and sql(f"select count(*)from public.member_task_completions where task_id='{first}';")=='1')
check('all login accounts preserved',sql('select count(*)from auth.users;')==accounts)
check('function privileges unchanged',sql("select jsonb_object_agg(proname,coalesce(proacl::text,''))from pg_proc where pronamespace='public'::regnamespace and proname in('task_app_setup','task_app_mark_absent','task_app_history_expires','task_app_fine_cutoff');")==grants)
rpc('task_app_setup',"'bootstrap',null",member)
check('bootstrap never recreates retired meeting and keeps four categories',sql(f"select count(*)from public.categories where owner_id='{owner}';")=='4')
expect('retired category cannot be created through RPC',"select public.task_app_setup('category','Woman''s Meeting');",owner,'23514')
expect('retired attendance cannot be marked',f"select public.task_app_mark_absent('{category}',null,true);",member,'23514')
for role in ['anon','authenticated','service_role']:
 sql(f"set role {role};select *from public.task_fine_candidates;",fail='42501')
for cat,start,day in [('Sunday Service','2026-10-11','2026-10-12'),('Healing Meeting','2026-10-14','2026-10-15'),('Revival Meeting','2026-10-16','2026-10-17'),('Special Meeting','2026-10-17','2026-10-18')]:
 check('four-category 05:00 India fine cutoff '+cat,sql(f"select public.task_app_fine_cutoff('{cat}','{start}','23:50')='{day}T05:00:00+05:30'::timestamptz;")=='t')
 check('four-category 23:50 India report cutoff '+cat,sql(f"select public.task_app_history_expires('{cat}','{start}T12:00:00+05:30','{start}','{{}}')='{day}T23:50:00+05:30'::timestamptz;")=='t')
check('retired category has no fine or report cutoff',sql("select public.task_app_fine_cutoff('Woman''s Meeting','2026-10-15','23:50')is null and public.task_app_history_expires('Woman''s Meeting',now(),null,'{}')is null;")=='t')
sql(migration,fail='already installed')
verification=sql((root/'supabase/verification/20261015_retire_meeting_schema_checks.sql').read_text())
check('post-retirement schema and privilege checks all zero',all(line.rsplit('|',1)[1]=='0'for line in verification.splitlines()))
print('Retirement021 isolated integration passed.',flush=True)
